const BASE = [21, 7, 12, 17];
function estimate(s, pct, p) {
  if (p.exam === "e" && s === "math" && p.ml === "b") {
    const prim = Math.round(pct * BASE[0]);
    return {
      kind: "grade",
      val: prim >= BASE[3] ? 5 : prim >= BASE[2] ? 4 : prim >= BASE[1] ? 3 : 2,
      prim,
      max: BASE[0],
    };
  }
  if (p.exam === "e") {
    const tb = EGE[s],
      max = tb.length,
      prim = Math.round(pct * max);
    return { kind: "test", val: prim ? tb[prim - 1] : 0, prim, max };
  }
  const o = OGE[s],
    prim = Math.round(pct * o[0]);
  return { kind: "grade", val: prim >= o[3] ? 5 : prim >= o[2] ? 4 : prim >= o[1] ? 3 : 2, prim, max: o[0] };
}
