Object.entries(FIGX).forEach(([id, m]) => {
  const t = T.find((x) => x.id === id);
  if (t)
    Object.entries(m).forEach(([i, f]) => {
      if (t.q[i]) t.q[i][2] = f;
    });
});
T.forEach((t) => {
  t.q.forEach((q, i) => {
    if (!q[3] && SOL[t.id] && SOL[t.id][i]) q[3] = SOL[t.id][i];
  });
  if (MORE[t.id]) MORE[t.id].forEach((m) => t.q.push([m[0], m[1], m[3] || null, m[2] || null]));
  if (G[t.id]) t.g = G[t.id];
});
FIX.forEach(([id, i, o]) => {
  const t = T.find((x) => x.id === id);
  if (!t || !t.q[i]) {
    console.warn("fix miss", id, i);
    return;
  }
  const q = t.q[i];
  if (o.t) q[0] = o.t;
  if (o.a) q[1] = o.a;
  if (o.add) q[1] = [...q[1], ...o.add];
  if (o.s) q[3] = o.s;
});
